"use strict";(self.webpackChunksalat_e_mustaqeem_client=self.webpackChunksalat_e_mustaqeem_client||[]).push([[4197],{74197:a=>{a.exports=JSON.parse('{"categories":{"prayer-times":"Prayer times","location":"Location","setup":"Your prayer settings","athan":"Athan","scheduled":"Automatic Athan","quran":"Quran and playback","hifz":"Hifz Coach","masjid":"My Masjid","ramadan":"Ramadan","islamic-calendar":"Qibla and the Islamic calendar","fasting":"Sunnah fasting","remembrance":"Adhkar, Tasbih and daily reminders","help":"Getting started"},"commands":{"Alexa, ask Muslim Companion what is my next prayer":{"does":"Says the next prayer, its time and how long until it, plus your masjid\'s iqamah if you follow one.","say":["Alexa, ask Muslim Companion what is my next prayer","Alexa, ask Muslim Companion when is the next prayer"]},"Alexa, ask Muslim Companion when is Maghrib":{"does":"Says the time for one prayer today (after Isha, Fajr is tomorrow\'s).","say":["Alexa, ask Muslim Companion when is Maghrib","Alexa, ask Muslim Companion what time is Fajr"]},"Alexa, ask Muslim Companion for today\'s prayer times":{"does":"Reads all of today\'s times. On an Echo Show it also shows them on screen with the next prayer and a countdown.","say":["Alexa, ask Muslim Companion for today\'s prayer times","Alexa, ask Muslim Companion for prayer times"]},"Alexa, ask Muslim Companion to use my Echo\'s location":{"does":"Sets your prayer times from your Echo\'s address (after you allow Device Address in the Alexa app). Only the city and approximate coordinates are kept.","say":["Alexa, ask Muslim Companion to use my Echo\'s location","Alexa, ask Muslim Companion to update my location"]},"Alexa, ask Muslim Companion for prayer times where I am":{"does":"In the Alexa app on your phone: prayer times where you are right now, for that answer only. Your Athans at home don\'t change.","say":["Alexa, ask Muslim Companion for prayer times where I am","Alexa, ask Muslim Companion for prayer times near me"]},"Yes":{"does":"Answers a question from Muslim Companion, such as whether to use your Echo\'s location.","say":["Yes","No"]},"Alexa, ask Muslim Companion to read my prayer settings":{"does":"Says your location, calculation method and Asr madhab, and how to change them.","say":["Alexa, ask Muslim Companion to read my prayer settings"]},"Alexa, ask Muslim Companion to set my calculation method to Umm al-Qura":{"does":"Changes how your prayer times are calculated: ISNA, Muslim World League, Umm al-Qura, Egyptian, Karachi, Gulf, Kuwait, Qatar, Singapore, France, Turkey, Russia, Tehran or Jafari. Alexa confirms with your new next prayer time and tells you how to go back.","say":["Alexa, ask Muslim Companion to set my calculation method to Umm al-Qura","Alexa, tell Muslim Companion to use the Muslim World League method","Alexa, tell Muslim Companion my masjid uses ISNA"]},"Alexa, ask Muslim Companion to set my madhab to Hanafi":{"does":"Sets the Asr time: Hanafi (later Asr), or standard for Shafi\'i, Maliki and Hanbali.","say":["Alexa, ask Muslim Companion to set my madhab to Hanafi","Alexa, tell Muslim Companion I follow the Hanafi madhab","Alexa, ask Muslim Companion to set my madhab to standard"]},"Alexa, ask Muslim Companion which calculation method should I use":{"does":"Suggests the method most used where you live (for example ISNA in North America, Turkey\'s Diyanet in Turkey) and offers to switch: say yes or no.","say":["Alexa, ask Muslim Companion which calculation method should I use"]},"Alexa, ask Muslim Companion what calculation method am I using":{"does":"Other ways to ask for your settings.","say":["Alexa, ask Muslim Companion what calculation method am I using","Alexa, ask Muslim Companion what is my madhab"]},"Alexa, ask Muslim Companion to play athan":{"does":"Plays the Athan now, with the Duas and Quran you chose after it. Voices you can name include Makkah, Madinah, Mishary and Zahrani.","say":["Alexa, ask Muslim Companion to play athan","Alexa, ask Muslim Companion to play athan in Makkah"]},"Alexa, ask Muslim Companion to play fajr athan":{"does":"Plays that prayer\'s Athan (Fajr uses its own Athan voice).","say":["Alexa, ask Muslim Companion to play fajr athan","Alexa, ask Muslim Companion to play maghrib athan"]},"Alexa, ask Muslim Companion to test athan":{"does":"Plays the Athan once so you can check the sound on this Echo.","say":["Alexa, ask Muslim Companion to test athan"]},"Alexa, ask Muslim Companion what is my scheduled athan status":{"does":"Tells you whether the automatic Athan is on.","say":["Alexa, ask Muslim Companion what is my scheduled athan status"]},"Alexa, ask Muslim Companion to enable scheduled athan":{"does":"Turns the automatic Athan on. It plays at each prayer time through your Alexa routine (see the Setup Guide).","say":["Alexa, ask Muslim Companion to enable scheduled athan"]},"Alexa, ask Muslim Companion to disable scheduled athan":{"does":"Turns the automatic Athan off for all prayers until you turn it on again.","say":["Alexa, ask Muslim Companion to disable scheduled athan"]},"Alexa, ask Muslim Companion to play Surah Al-Kahf":{"does":"Plays any surah by name or number, said the way you say it (Fatiha or Fateha, Baqarah or Surah Baqara, Nisa\u2026), with your reciter or the one you name (Qari Badar, Maher, Al-Muaiqly, Sudais\u2026), or with an English or Urdu translation after each ayah.","say":["Alexa, ask Muslim Companion to play Surah Al-Kahf","Alexa, ask Muslim Companion to play Surah Baqarah by Qari Badar","Alexa, ask Muslim Companion to play Fatiha by Maher","Alexa, ask Muslim Companion to play surah number 36","Alexa, ask Muslim Companion to play Surah Yasin with English translation"]},"Alexa, ask Muslim Companion to read along Surah Al-Kahf":{"does":"On an Echo Show 8 or larger, shows the Madinah mushaf page by page in tajweed colours while Maher Al-Muaiqly recites. The verse being recited is lit up, the page turns by itself, and you can tap a verse to recite from there. Say next page, previous page, pause or resume. The Echo Show 15 adds the translation beside the page.","say":["Alexa, ask Muslim Companion to read along Surah Al-Kahf","Alexa, ask Muslim Companion to open mushaf page 293"],"soonNote":"Mushaf read-along is being tested on Echo Show."},"Alexa, ask Muslim Companion which reciters do you have":{"does":"Lists the reciters, or the ones whose name starts with a letter. If Alexa doesn\'t know a reciter you name, it suggests the ones starting with the same letter.","say":["Alexa, ask Muslim Companion which reciters do you have","Alexa, ask Muslim Companion which reciters start with S"]},"Alexa, ask Muslim Companion to turn on Friday Kahf":{"does":"Every Friday, Surah Al-Kahf plays after the Fajr Athan (or Dhuhr, set on the dashboard).","say":["Alexa, ask Muslim Companion to turn on Friday Kahf","Alexa, ask Muslim Companion to turn off Friday Kahf"]},"Alexa, next":{"does":"While the Quran plays: the next or previous surah. During the Athan and Duas, Next skips ahead.","say":["Alexa, next","Alexa, previous"]},"Alexa, start over":{"does":"Starts the current surah again.","say":["Alexa, start over"]},"Alexa, pause":{"does":"Pauses the recitation and carries on from the same place.","say":["Alexa, pause","Alexa, resume"]},"Alexa, stop":{"does":"Stops the Athan or recitation at any time.","say":["Alexa, stop","Alexa, cancel"]},"Alexa, ask Muslim Companion how far am I in the Quran":{"does":"Tells you your Quran Journey: listening time and how much of the khatm you have heard.","say":["Alexa, ask Muslim Companion how far am I in the Quran"]},"Alexa, shuffle":{"does":"Explains how to choose Random or continuous Quran on the Quran Schedule page.","say":["Alexa, shuffle","Alexa, loop"]},"Alexa, ask Muslim Companion to start Hifz":{"does":"Plays your current lesson: each ayah repeated, then the whole lesson together. On an Echo Show the ayah appears on screen.","say":["Alexa, ask Muslim Companion to start Hifz"]},"Alexa, tell Muslim Companion I memorized it":{"does":"Marks the lesson memorized and moves to the next one.","say":["Alexa, tell Muslim Companion I memorized it"]},"Alexa, ask Muslim Companion to repeat each ayah five times":{"does":"Sets how many times each ayah repeats: 1, 3, 5, 7 or 10.","say":["Alexa, ask Muslim Companion to repeat each ayah five times"]},"Alexa, ask Muslim Companion how is my Hifz":{"does":"Tells you how many ayahs you have memorized and your current lesson.","say":["Alexa, ask Muslim Companion how is my Hifz"]},"Alexa, ask Muslim Companion to link my phone":{"does":"Links this Echo to your Salat-e-Mustaqeem phone account with the six-digit code from the app (More, then Alexa), so your Hifz progress shows on the phone.","say":["Alexa, ask Muslim Companion to link my phone","Alexa, ask Muslim Companion to link my phone with code 123456"]},"Alexa, ask Muslim Companion when is iqamah":{"does":"Says the next iqamah time at the masjid you follow.","say":["Alexa, ask Muslim Companion when is iqamah"]},"Alexa, ask Muslim Companion when is jumuah":{"does":"Says this week\'s Jumu\'ah time or times at your masjid.","say":["Alexa, ask Muslim Companion when is jumuah"]},"Alexa, ask Muslim Companion to turn on Ramadan mode":{"does":"Turns Ramadan mode on or off: Suhoor reminder, Iftar at Maghrib and Taraweeh recitation after Isha.","say":["Alexa, ask Muslim Companion to turn on Ramadan mode","Alexa, ask Muslim Companion to turn off Ramadan mode"]},"Alexa, ask Muslim Companion is Ramadan mode on":{"does":"Tells you whether Ramadan mode is on.","say":["Alexa, ask Muslim Companion is Ramadan mode on"]},"Alexa, ask Muslim Companion when is suhoor":{"does":"Says when Suhoor ends (Fajr) and when Iftar is (Maghrib).","say":["Alexa, ask Muslim Companion when is suhoor","Alexa, ask Muslim Companion when is iftar"]},"Alexa, ask Muslim Companion which way is the Qibla":{"does":"Says the Qibla direction from your saved location in degrees from true north and as a compass point, and how far Makkah is.","say":["Alexa, ask Muslim Companion which way is the Qibla","Alexa, ask Muslim Companion where is the Qibla"]},"Alexa, ask Muslim Companion what is the Hijri date":{"does":"Says today\'s Hijri date (the same date as the app and your Echo Show), and if today is a special day.","say":["Alexa, ask Muslim Companion what is the Hijri date","Alexa, ask Muslim Companion what is the Islamic date today"]},"Alexa, ask Muslim Companion when is Ramadan":{"does":"When Ramadan, Eid, Ashura, Arafah, the Islamic New Year, the last ten nights or the white days are, with a countdown. Dates follow Umm al-Qura and can differ by a day where the moon is sighted locally.","say":["Alexa, ask Muslim Companion when is Ramadan","Alexa, ask Muslim Companion how many days until Eid","Alexa, ask Muslim Companion when are the white days"]},"Alexa, ask Muslim Companion when is the next Sunnah fast":{"does":"The next Sunnah fast: Mondays and Thursdays, the white days, Arafah, Ashura and the six days of Shawwal.","say":["Alexa, ask Muslim Companion when is the next Sunnah fast","Alexa, ask Muslim Companion should I fast tomorrow"]},"Alexa, ask Muslim Companion to turn on fasting reminders":{"does":"A reminder after Isha on the evening before a Sunnah fast, through your Muslim Companion routine.","say":["Alexa, ask Muslim Companion to turn on fasting reminders","Alexa, ask Muslim Companion to turn off fasting reminders"]},"Alexa, ask Muslim Companion to play the morning adhkar":{"does":"Ayat al-Kursi, then Al-Ikhlas, Al-Falaq and An-Nas three times each, recited.","say":["Alexa, ask Muslim Companion to play the morning adhkar","Alexa, ask Muslim Companion to play the evening adhkar"]},"Alexa, ask Muslim Companion to turn on morning and evening adhkar":{"does":"Plays the morning adhkar after Fajr and the evening adhkar after Asr every day (or Maghrib, set on the dashboard).","say":["Alexa, ask Muslim Companion to turn on morning and evening adhkar","Alexa, ask Muslim Companion to turn off evening adhkar"]},"Alexa, ask Muslim Companion to start tasbih":{"does":"Counts dhikr with you at a gentle pace. With no dhikr named, it leads the tasbih after the prayer: 33 SubhanAllah, 33 Alhamdulillah and 34 Allahu Akbar. On an Echo Show, tap the screen to count.","say":["Alexa, ask Muslim Companion to start tasbih","Alexa, ask Muslim Companion to count 33 subhanallah"]},"Alexa, ask Muslim Companion for today\'s dua":{"does":"A short daily dua, hadith or Name of Allah with its source, reviewed by a scholar before it is published.","say":["Alexa, ask Muslim Companion for today\'s dua","Alexa, ask Muslim Companion for today\'s hadith","Alexa, ask Muslim Companion for the name of allah of the day"],"soonNote":"Coming soon: each dua, hadith and Name is checked by a scholar first"},"Alexa, open Muslim Companion":{"does":"Starts the skill (it plays the Athan for the current prayer).","say":["Alexa, open Muslim Companion"]},"Alexa, ask Muslim Companion for help":{"does":"Lists what you can ask.","say":["Alexa, ask Muslim Companion for help"]}}}')}}]);